// CloudtainerML rev0030 — Spectral/operator HPO sweep.
// Hardens the CHIAR-style operator-routing lane with actual DCT/IDCT transforms,
// held-out regimes, and threshold/residual-budget tuning. This is a tiny wind tunnel,
// not a paper reproduction.
#include <bits/stdc++.h>
using namespace std;
static const double PI = acos(-1.0);
static string q(const string& s){ string o="\""; for(char c:s){ if(c=='\"'||c=='\\') o+='\\'; if(c=='\n') o+="\\n"; else o+=c;} return o+'\"'; }
struct Regime{string name; double low, high, local, sparse, noise, alias; int base_seed;};
struct Case{Regime r; int N,budget,seed;};
struct Row{string split,regime,method,config; int N,budget,seed; double target,out,abs_error,cost_frac,budget_over,alias_error,tail_miss,regret,score;};
struct Cfg{string name; double ent_lo, alias_hi, local_hi, sparse_hi, residual_frac, lowpass_frac;};
static vector<double> dct(const vector<double>&x){int N=x.size(); vector<double> c(N); double s0=sqrt(1.0/N), s=sqrt(2.0/N); for(int k=0;k<N;k++){double sum=0; for(int n=0;n<N;n++) sum += x[n]*cos(PI*(n+0.5)*k/N); c[k]=sum*(k==0?s0:s);} return c;}
static vector<double> idct_keep(const vector<double>&c,const vector<int>&keep){int N=c.size(); vector<char> m(N,0); for(int i:keep) if(0<=i&&i<N)m[i]=1; vector<double>x(N); double s0=sqrt(1.0/N), s=sqrt(2.0/N); for(int n=0;n<N;n++){double sum=0; for(int k=0;k<N;k++) if(m[k]) sum += c[k]*(k==0?s0:s)*cos(PI*(n+0.5)*k/N); x[n]=sum;} return x;}
static vector<int> topk(const vector<double>&s,int k){int N=s.size(); k=max(1,min(k,N)); vector<int> idx(N); iota(idx.begin(),idx.end(),0); nth_element(idx.begin(),idx.begin()+k-1,idx.end(),[&](int a,int b){return s[a]>s[b];}); idx.resize(k); sort(idx.begin(),idx.end()); return idx;}
static vector<double> softmax(const vector<double>&logits,const vector<char>&mask){int N=logits.size(); double mx=-1e300; for(int i=0;i<N;i++) if(mask[i]) mx=max(mx,logits[i]); vector<double>w(N); if(mx<-1e200)return w; double z=0; for(int i=0;i<N;i++) if(mask[i]){w[i]=exp(logits[i]-mx); z+=w[i];} if(z>0) for(double&v:w)v/=z; return w;}
static double dot(const vector<double>&a,const vector<double>&b){double z=0; for(size_t i=0;i<a.size();++i) z+=a[i]*b[i]; return z;}
static double spec_entropy(const vector<double>&c){double z=0; for(double v:c) z+=v*v; if(z<=1e-12) return 0; double h=0; for(double v:c){double p=v*v/z; if(p>1e-12) h-=p*log(p);} return h/log((double)c.size());}
struct Sig{vector<double> value, logits; int qpos; vector<int> needles; double ent, hi_frac, loc_proxy, sparse_proxy;};
static Sig make_sig(const Case&ca){auto r=ca.r; int N=ca.N; mt19937_64 rng(0xC10D3ULL + ca.seed*131 + r.base_seed*17 + N); normal_distribution<double> nd(0,1); vector<double>x(N),logits(N,-2.0); int qpos=N/2 + ((ca.seed%9)-4)*max(1,N/96); int f_low=1+(ca.seed%3); int f_hi=max(2,(int)round((0.14+0.19*r.alias)*N)); for(int i=0;i<N;i++){double t=(i+0.5)/N; double low=r.low*(sin(2*PI*f_low*t)+0.42*cos(2*PI*(f_low+2)*t+0.2)); double hi=r.high*(0.7*sin(2*PI*f_hi*t+0.3)+0.35*cos(2*PI*(f_hi+5)*t)); double loc=r.local*exp(-0.5*pow((i-qpos)/(0.045*N+2.0),2)); double noise=r.noise*0.32*nd(rng); x[i]=low+hi+1.7*loc+noise; logits[i]=0.35*low+0.20*hi+0.95*loc-0.04*fabs(noise);}
 int nc=max(1,(int)round(1+r.sparse*5)); vector<int> needles; for(int j=0;j<nc;j++){int p=(ca.seed*37 + 17*j + N/4 + j*N/nc)%N; needles.push_back(p); x[p]+=2.5+1.2*r.sparse; logits[p]+=2.6+1.0*r.sparse;}
 int ac=(int)round(r.alias*6); for(int j=0;j<ac;j++){int p=(ca.seed*11 + 29*j + N/3)%N; x[p]-=1.9*r.alias; logits[p]+=0.9*r.alias;}
 auto c=dct(x); double ent=spec_entropy(c); double total=0,hi=0; for(int k=0;k<N;k++){double e=c[k]*c[k]; total+=e; if(k>N/5)hi+=e;} double locp=0; for(int d=-max(1,N/16); d<=max(1,N/16); ++d){int p=qpos+d; if(0<=p&&p<N) locp += exp(logits[p]);} double all=0; for(double v:logits) all+=exp(v); return {x,logits,qpos,needles,ent,total>0?hi/total:0,locp/max(1e-9,all),min(1.0,(double)needles.size()/6.0)};}
static Row eval_method(const Case&ca,const string&method,const string&cfgname="manual", const Cfg*cfg=nullptr){auto s=make_sig(ca); int N=ca.N; int K=max(2,(int)round(N*ca.budget/100.0)); vector<char> all(N,1); auto wf=softmax(s.logits,all); double target=dot(wf,s.value); double out=0,cost=1,aliaserr=0,tail=0; string m=method; if(m=="router_hpo" && cfg){ if(s.sparse_proxy>cfg->sparse_hi || s.hi_frac>cfg->alias_hi) m="topk_attention"; else if(s.loc_proxy>cfg->local_hi && s.ent>cfg->ent_lo) m="local_window"; else if(s.ent<cfg->ent_lo && s.hi_frac<cfg->alias_hi) m="dct_lowpass"; else m="dct_attention_residual"; }
 if(m=="full_attention"){out=target; cost=1.0;}
 else if(m=="topk_attention"){auto idx=topk(s.logits,K); vector<char> mask(N,0); for(int i:idx)mask[i]=1; auto w=softmax(s.logits,mask); out=dot(w,s.value); cost=(double)K/N+0.04; for(int p:s.needles) if(!mask[p]) tail+=1; tail/=max(1,(int)s.needles.size());}
 else if(m=="local_window"){int W=max(1,K/2); vector<char> mask(N,0); for(int d=-W;d<=W;d++){int p=s.qpos+d; if(0<=p&&p<N)mask[p]=1;} auto w=softmax(s.logits,mask); out=dot(w,s.value); cost=(double)count(mask.begin(),mask.end(),1)/N+0.02; for(int p:s.needles) if(!mask[p]) tail+=1; tail/=max(1,(int)s.needles.size());}
 else if(m=="dct_lowpass"){auto c=dct(s.value); int kc=max(1,(int)round(K*(cfg?cfg->lowpass_frac:0.80))); vector<int> keep; for(int i=0;i<min(kc,N);i++)keep.push_back(i); auto rec=idct_keep(c,keep); out=dot(wf,rec); cost=(double)kc/N*0.55+0.055; aliaserr=s.hi_frac*0.75; tail=0.30*s.sparse_proxy;}
 else {auto c=dct(s.value); double rf=cfg?cfg->residual_frac:0.50; int kt=max(1,(int)round(K*rf)); int kc=max(1,K-kt); vector<int> keep; for(int i=0;i<min(kc,N);i++)keep.push_back(i); auto rec=idct_keep(c,keep); auto idx=topk(s.logits,kt); vector<char> mask(N,0); for(int i:idx)mask[i]=1; vector<double> approx=rec; for(int i:idx)approx[i]=s.value[i]; out=dot(wf,approx); cost=(double)(kc*0.55+kt)/N+0.08; aliaserr=s.hi_frac*0.24; for(int p:s.needles) if(!mask[p]) tail+=1; tail/=max(1,(int)s.needles.size());}
 double err=fabs(out-target), budget=ca.budget/100.0, over=max(0.0,cost-budget), score=err+0.60*over+0.20*aliaserr+0.24*tail+0.05*cost; return {"",ca.r.name,method,cfgname,N,ca.budget,ca.seed,target,out,err,cost,over,aliaserr,tail,0,score};}
int main(int argc,char**argv){string outp=argc>1?argv[1]:"REV0030_SPECTRAL_OPERATOR_HPO_SWEEP_SMOKE.json"; vector<Regime> regs={{"smooth_naturalistic",.96,.05,.20,.08,.08,.04,1},{"alias_highfreq_trap",.18,.94,.18,.24,.10,.96,2},{"needle_sparse_long",.32,.22,.20,.98,.12,.25,3},{"local_burst",.38,.20,.94,.18,.10,.20,4},{"mixed_code_like",.46,.58,.42,.48,.14,.58,5},{"noisy_small_data",.38,.36,.34,.34,.62,.42,6}}; vector<int> Ns={64,128}, budgets={20,32,50}; vector<Cfg> cfgs; for(double ent:{0.30,0.50}) for(double alias:{0.30,0.55}) for(double local:{0.15,0.30}) for(double sparse:{0.35,0.65}) for(double rf:{0.40,0.65}) cfgs.push_back({"e"+to_string((int)(ent*100))+"_a"+to_string((int)(alias*100))+"_l"+to_string((int)(local*100))+"_s"+to_string((int)(sparse*100))+"_r"+to_string((int)(rf*100)),ent,alias,local,sparse,rf,1-rf*0.5});
 vector<Case> train,test; for(auto&r:regs) for(int N:Ns) for(int b:budgets) for(int seed=0;seed<6;seed++){Case ca{r,N,b,seed}; if(seed<3 && r.name!="mixed_code_like") train.push_back(ca); else test.push_back(ca);} vector<double> cfgTrain(cfgs.size()); for(size_t ci=0;ci<cfgs.size();++ci){double z=0; for(auto&ca:train) z+=eval_method(ca,"router_hpo",cfgs[ci].name,&cfgs[ci]).score; cfgTrain[ci]=z/train.size();} size_t besti=min_element(cfgTrain.begin(),cfgTrain.end())-cfgTrain.begin(); Cfg best=cfgs[besti]; vector<string> baselines={"topk_attention","local_window","dct_lowpass","dct_attention_residual"}; vector<Row> rows; map<string,int>winners, nonoracle; for(auto splitCases : {pair<string,vector<Case>*>("train",&train), pair<string,vector<Case>*>("test",&test)}){ for(auto&ca:*splitCases.second){vector<Row> cand; for(auto&m:baselines) cand.push_back(eval_method(ca,m,m,nullptr)); cand.push_back(eval_method(ca,"router_hpo","selected_"+best.name,&best)); // per-case oracle over same non-full candidates
 Row oracle=cand[0]; for(auto&r:cand) if(r.score<oracle.score) oracle=r; oracle.method="oracle_nonfull"; oracle.config="per_case"; cand.push_back(oracle); for(auto &r:cand) r.split=splitCases.first; double bestScore=1e9; for(auto&r:cand) bestScore=min(bestScore,r.score); for(auto&r:cand){r.regret=max(0.0,r.score-bestScore); rows.push_back(r);} if(splitCases.first=="test"){auto b=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); winners[b->method]++; auto nb=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){if(a.method=="oracle_nonfull")return false; if(b.method=="oracle_nonfull")return true; return a.score<b.score;}); nonoracle[nb->method]++;}}}
 ofstream f(outp); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0030\",\n  \"probe\": \"spectral_operator_hpo_sweep\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"selected_config\": "<<q(best.name)<<",\n    \"selected_train_score\": "<<cfgTrain[besti]<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:winners){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:nonoracle){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"Held-out operator HPO tests whether DCT/spectral compression needs attention residuals and threshold tuning; useful only if it beats fixed DCT+attention on held-out regimes without hiding alias/tail misses.\",\n    \"screen_regret_fields\": [\"abs_error\",\"cost_frac\",\"budget_over\",\"alias_error\",\"tail_miss\",\"regret\",\"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"split\": "<<q(r.split)<<", \"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"config\": "<<q(r.config)<<", \"n\": "<<r.N<<", \"budget_pct\": "<<r.budget<<", \"seed\": "<<r.seed<<", \"target\": "<<r.target<<", \"out\": "<<r.out<<", \"abs_error\": "<<r.abs_error<<", \"cost_frac\": "<<r.cost_frac<<", \"budget_over\": "<<r.budget_over<<", \"alias_error\": "<<r.alias_error<<", \"tail_miss\": "<<r.tail_miss<<", \"regret\": "<<r.regret<<", \"score\": "<<r.score<<"}"<<(i+1<rows.size()?",":"")<<"\n";} f<<"  ]\n}\n"; return 0;}
